import antfu from '@antfu/eslint-config'

export default antfu(
  {
    type: 'app',
    solid: true,
    typescript: true,
    formatters: false,
    ignores: [
      'dist/',
      '**/dist/',
      '.rspeedy/',
      '**/.rspeedy/',
      '.rslib/',
      '**/.rslib/',
      'compile-lab/.build/',
      // Generated by filesystem-routing (regenerates on route changes).
      'compile-lab/file-routes.d.ts',
      // Generated by @tanstack/router-plugin (regenerates on route changes).
      'examples/elk/src/routeTree.gen.ts',
      '**/generated/**',
      // Fork of dom-expressions — keep diffs minimal for upstream syncs.
      // Per ESLint docs: `dir/**` prunes traversal entirely so a negation
      // can never hit; use `dir/**/*` (contents only) + un-ignore all
      // subdirectories, then pick back our extracted file.
      'packages/compiler/babel-plugin-jsx-lynx/**/*',
      '!packages/compiler/babel-plugin-jsx-lynx/**/',
      '!packages/compiler/babel-plugin-jsx-lynx/**/lynx-worklet.ts',
      // Generated by @tanstack/router-plugin (regenerates on route changes).
      'examples/hackernews/src/routeTree.gen.ts',
      // Docs site generated output (prepare-examples copies + rspress build).
      'website/docs/public/examples/**',
      'website/dist/',
      'website/doc_build/',
      'website/.rspress/',
    ],
  },
  {
    // Lynx inline styles are CSS strings ("display:linear;width:100%") with
    // engine-specific properties (linear-direction etc.) — the solid plugin's
    // object-literal rewrite breaks both the compiler contract and tsc.
    name: 'custom/lynx-overrides',
    rules: {
      'solid/style-prop': 'off',
      'no-console': 'off',
      // Its autofix rewrites `setTimeout(() => fn(a, b), ms)` to ES5
      // arg-forwarding — browser-only semantics. Lynx host timers (BG
      // js_app.cc, MT napi_lepus_lynx.cc) drop forwarded args and fire the
      // callback zero-arg, so the rewritten form passes `undefined` on device
      // while web works. The portable arrow-wrapper form is enforced by the
      // two-arg timer types exported from @lynx-solid/runtime instead: a
      // forwarded call fails typecheck with TS2554.
      'e18e/prefer-timer-args': 'off',
    },
  },
  {
    // The project runs solid-js@2.0.0-rc.0, but the plugin's version-aware
    // rules only switch to 2.0 semantics via this setting (no auto-detect).
    name: 'custom/solid-v2',
    settings: {
      solid: { version: '2' },
    },
  },
  {
    files: ['packages/runtime/src/**/*.ts'],
    name: 'custom/lynx-runtime-globals',
    languageOptions: {
      globals: {
        // Native Lepus/MT PAPI surface — injected by the engine, no import exists
        __AddEvent: 'readonly',
        __AppendElement: 'readonly',
        __CreateElement: 'readonly',
        __CreateList: 'readonly',
        __CreateText: 'readonly',
        __GetElementUniqueID: 'readonly',
        __SetAttribute: 'readonly',
        __SetClasses: 'readonly',
        __SetCSSId: 'readonly',
        __SetID: 'readonly',
        __SetInlineStyles: 'readonly',
        __SetStyleProp: 'readonly',
        define: 'readonly',
        requireModule: 'readonly',
        runWorklet: 'readonly',
        registerWorklet: 'readonly',
        registerSkeleton: 'readonly',
        SystemInfo: 'readonly',
      },
    },
    rules: {
      // Engine callbacks and generated-code dispatch legitimately need bare
      // identifiers; strict undefined checks are handled by tsc.
      'no-undef': 'off',
    },
  },
  {
    files: ['tests/**/*.ts', '**/*.test.ts'],
    name: 'custom/tests',
    rules: {
      // Behavior tests intentionally poke module internals and use eval to
      // instantiate compiled createCode literals.
      'ts/no-explicit-any': 'off',
      'eslint-comments/no-unlimited-disable': 'off',
      'node/prefer-global/process': 'off',
      // Test titles deliberately lead with the API under test
      // ("Object.hasOwn …", "Array at …") — capitalization is meaningful.
      'test/prefer-lowercase-title': 'off',
    },
  },
  {
    files: ['examples/**/*.tsx', 'examples/**/*.ts', 'compile-lab/**/*.tsx', 'compile-lab/**/*.ts', 'website/src/**/*.tsx', 'website/src/**/*.ts', 'website/scripts/**/*.mjs', 'website/*.ts'],
    name: 'custom/dev-samples',
    rules: {
      // Sample apps: console-driven demos, loose typing is fine.
      'no-console': 'off',
      'ts/no-explicit-any': 'off',
    },
  },
  {
    // Lynx polyfills/shims are eval-order-sensitive: `import './polyfills'`
    // must run before modules that touch bare globals at module scope.
    // antfu's default groups include 'side-effect', which forces those
    // imports after all value imports — perfectionist's sortSideEffects:false
    // protection then never applies. Omitting 'side-effect' from groups
    // restores "side-effect imports stay where you write them"; value
    // imports still sort normally. Rule options replace wholesale, so the
    // rest of antfu's options must be restated.
    name: 'custom/sort-imports-keep-side-effect-position',
    rules: {
      'perfectionist/sort-imports': ['error', {
        groups: [
          'type-import',
          [
            'type-parent',
            'type-sibling',
            'type-index',
            'type-internal',
          ],
          'value-builtin',
          'value-external',
          'value-internal',
          [
            'value-parent',
            'value-sibling',
            'value-index',
          ],
          // 'side-effect' intentionally omitted — see comment above.
          'ts-equals-import',
          'unknown',
        ],
        newlinesBetween: 'ignore',
        newlinesInside: 'ignore',
        order: 'asc',
        type: 'natural',
      }],
    },
  },
)
